const icon=(name)=>`<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
function hydrateIcons(){for(const e of $$('[data-icon]'))e.innerHTML=icon(e.dataset.icon);}
const defaults={theme:'light',fontSize:34,reciter:'ar.alafasy',repeat:3,pause:2,cycles:1,speed:1,loopStyle:'verse',goal:10,goalUnit:'minutes',memorized:[1,112,113,114],saveRecordings:false,feedback:'after',speechMode:'browser',cloudEndpoint:'https://api.groq.com/openai/v1/audio/transcriptions',cloudModel:'whisper-large-v3-turbo',allowCloud:false,reviewFirst:false,favouriteReciters:[],followRecitation:true};
let persisted={};try{persisted=JSON.parse(localStorage.getItem('hifz.v1')||'{}');}catch{}
const state={settings:{...defaults,...persisted.settings},progress:persisted.progress||{},mistakes:persisted.mistakes||[],hints:persisted.hints||{},sessions:persisted.sessions||[],bookmarks:persisted.bookmarks||[],selection:persisted.selection||{surah:1,from:1,to:3},view:'practice',mode:'read',guest:false,hidden:false,hintCount:0,quiz:null,filter:'all'};
let quran=[],reciters=[],recordings=[],db=null,apiKey='',storageFailed=false,recognition=null,listening=false,stopping=false,heardBase='',latestTranscript='',latestAlignment=null,sessionStarted=0,recognitionErrors=0,restartTimer=null,recordStream=null,recorder=null,recordChunks=[],recording=false,micCleanup=null,toastTimer=null,audioQueue=[],queueIndex=0,audioGeneration=0,queueTimer=null,audioBlobUrl=null,testAfterAudio=false;
let speechStatus='Tap Start listening, allow the microphone, then recite.',speechProblem='',speechTimer=null,finishTimer=null,finishing=false,findingPassage=false,chapterPlayback=false;
const audio=new Audio();audio.preload='none';
function save(){if(state.guest)return;try{localStorage.setItem('hifz.v1',JSON.stringify({settings:state.settings,progress:state.progress,mistakes:state.mistakes.slice(-500),hints:state.hints,sessions:state.sessions.slice(-200),bookmarks:state.bookmarks,selection:state.selection}));}catch{if(!storageFailed){storageFailed=true;toast('Storage is full or unavailable. Export your progress to keep it.');}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
const current=()=>quran[state.selection.surah-1];
const selected=()=>current().verses.filter(v=>v.n>=state.selection.from&&v.n<=state.selection.to);
const ref=v=>`${state.selection.surah}:${v.n}`;
const verseRef=(s,n)=>quran[s-1]?.verses[n-1];
const dateKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const dueEntries=()=>Object.entries(state.progress).filter(([,p])=>p.due&&p.due<=Date.now()).sort((a,b)=>a[1].due-b[1].due);
function setTheme(){document.body.classList.toggle('dark',state.settings.theme==='dark');document.documentElement.style.setProperty('--arabic-size',`${state.settings.fontSize/16}rem`);}
function openModal(title,html){stopMicCheck();$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;hydrateIcons();if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(findingPassage){stopListening(false);findingPassage=false;}stopMicCheck();$('#modal').close();}
function setSelection(s,from,to){if(recording){toast('Stop your recording before changing passages.');return;}stopListening(false);stopAudio();s=Math.max(1,Math.min(114,Number(s)));const count=quran[s-1].verses.length;from=Math.max(1,Math.min(count,Number(from)||1));to=Math.max(from,Math.min(count,Number(to)||from));speechStatus='Tap Start listening, allow the microphone, then recite.';speechProblem='';state.selection={surah:s,from,to};state.quiz=null;state.hintCount=0;latestAlignment=null;latestTranscript='';save();render();}
function navigate(view){if(recording){toast('Stop your recording before leaving this passage.');return;}if(listening)stopListening(true);state.view=view;location.hash=view;render();}
function render(){setTheme();document.body.classList.toggle('reciting',state.view==='practice'&&['recite','test'].includes(state.mode));for(const e of $$('[data-view]'))e.classList.toggle('active',e.dataset.view===state.view);$('#due-count').textContent=dueEntries().length;$('#breadcrumb').textContent=state.guest?'Guest practice · progress will not be saved':({practice:'Your daily practice',library:'Explore the Qur’an',revision:'Keep what you have learned',progress:'Your memorization journey'}[state.view]);$('#app-content').innerHTML=state.view==='practice'?practiceHTML():state.view==='library'?libraryHTML():state.view==='revision'?revisionHTML():progressHTML();hydrateIcons();if(state.view==='practice'){updateRecitation();bindPractice();}if(state.view==='library')$('#surah-search')?.addEventListener('input',filterLibrary);}
function practiceHTML(){const s=current(),sel=state.selection,completedToday=state.sessions.filter(x=>x.day===dateKey()).length;return `
<section class="greeting"><div><div class="eyebrow">${esc(new Date().toLocaleDateString(undefined,{weekday:'long'}))}’s practice</div><h1>A little every day.</h1><p class="muted">${completedToday?'You have already made time for your Qur’an today.':'Begin with a verse. Build a lasting connection.'}</p></div><span class="date-chip">${esc(new Date().toLocaleDateString(undefined,{month:'long',day:'numeric'}))}</span></section>
<div class="daily-plan"><button class="plan-step" data-action="due-review"><span class="step-number">01</span><span><strong>Older revision</strong><small>${dueEntries().length?dueEntries().length+' passages due':'Choose a familiar passage'}</small></span></button><button class="plan-step" data-action="recent-review"><span class="step-number">02</span><span><strong>Recent practice</strong><small>${state.sessions.length?'Return to your last lesson':'Keep yesterday’s verses close'}</small></span></button><button class="plan-step" data-action="new-lesson"><span class="step-number">03</span><span><strong>New memorization</strong><small>Listen, repeat, then connect</small></span></button></div>
<div class="workspace"><section class="reader" aria-label="Quran passage"><div class="reader-head"><div class="reader-heading"><h2>${esc(s.nameEn)}</h2><p>${esc(s.meaning)} · Verses ${sel.from}–${sel.to}</p></div><div class="surah-arabic" lang="ar" dir="rtl">${esc(s.name)}</div></div>
<div class="modes" role="tablist" aria-label="Practice mode">${[['read','Read'],['memorize','Memorize'],['recite','Recite'],['test','Test myself']].map(([m,label])=>`<button role="tab" aria-selected="${state.mode===m}" data-mode="${m}" class="${state.mode===m?'active':''}">${label}</button>`).join('')}</div>
${state.mode==='recite'||state.mode==='test'?recitationControls():''}<div class="verses" id="verses">${versesHTML()}</div><div class="reader-foot"><button data-action="prev-passage">Previous passage</button><span>Page ${selected()[0].page} · Juz ${selected()[0].juz}</span><button data-action="next-passage">Next passage</button></div></section>
<aside class="practice-panel"><div class="panel-title"><div class="eyebrow">${state.mode==='test'?'A little challenge':'Your practice'}</div><h2>${{read:'Listen to your passage',memorize:'Make it familiar',recite:'Recite at your own pace',test:'Continue from memory'}[state.mode]}</h2><p class="small">${{read:'Choose a qāri and follow along.',memorize:'Hear it. Repeat it. Connect the verses.',recite:'Select your passage, then begin reciting.',test:'Hear a prompt, then recite what comes next.'}[state.mode]}</p></div>
<div class="field-group"><label for="surah-select">Surah</label><select id="surah-select">${quran.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${x.id}. ${esc(x.nameEn)}</option>`).join('')}</select></div>
<div class="field-row"><div><label for="from-verse">From verse</label><input id="from-verse" type="number" min="1" max="${s.verses.length}" value="${sel.from}"></div><div><label for="to-verse">To verse</label><input id="to-verse" type="number" min="${sel.from}" max="${s.verses.length}" value="${sel.to}"></div></div>
<div class="field-group"><label>Reciter</label><button class="secondary wide" data-action="reciter">${icon('headphones')}${esc(reciterName())}</button></div>
${state.mode==='test'?`<button class="primary wide" data-action="quiz">${icon('spark')}Give me a random test</button><button class="secondary wide" data-action="quiz-options">Choose test range</button>`:''}
${state.mode==='recite'||state.mode==='test'?`<button class="secondary wide" data-action="find-voice">Find my passage by voice</button><button class="secondary wide" data-action="weak-practice">Practise my weak verses</button>`:`<button class="primary wide" data-action="play">${icon('play')}${state.mode==='memorize'?'Listen & repeat':reciters.find(r=>r.id===state.settings.reciter)?.kind==='surah'?'Play full surah':'Play recitation'}</button>${state.mode==='memorize'?'<button class="secondary wide" data-action="hide">'+(state.hidden?'Reveal passage':'Hide passage')+'</button><button class="text-button wide" data-action="hint">Give me a hint</button>':''}`}
${state.mode==='memorize'?`<button class="secondary wide" data-action="playback-settings">${icon('repeat')}${state.settings.repeat} repeats · ${state.settings.loopStyle==='connect'?'Connect verses':state.settings.loopStyle==='passage'?'Whole passage':'Verse by verse'}</button><button class="text-button wide" data-action="recite-now">I’m ready to recite</button>`:''}


<div class="divider"></div><button class="secondary wide" data-action="record">${icon('mic')}${recording?'Stop & save my recording':'Record myself'}</button><button class="text-button wide" data-action="mic-check">Check my microphone</button><button class="text-button wide" data-action="mark-practice">Mark passage practised</button>
</aside></div>
<div class="tip">${icon('spark')}<p><strong>${state.mode==='memorize'?'Connect, don’t just repeat.':'Let revision lead the way.'}</strong> ${state.mode==='memorize'?'Try verse 1, then 1–2, then 1–3. Choose “Connect verses” in repetition settings.':'A short review of older verses helps keep yesterday’s effort with you.'}</p></div>`;}
function recitationControls(){return `<section class="recitation-controls" aria-label="Recitation controls"><div class="button-row"><button class="primary" id="listen-button" data-action="listen" ${finishing?'disabled':''}>${icon(listening?'pause':'mic')}${finishing?'Finishing…':listening?'Finish recitation':'Start listening'}</button><button class="secondary" data-action="mic-guide">Phone setup</button></div><div id="listening-state" class="listening-status" role="status" aria-live="polite"><span class="listening-dot" ${listening?'':'hidden'}></span><span id="listen-status">${esc(speechStatus)}</span></div><div id="speech-problem" class="speech-problem" ${speechProblem?'':'hidden'}>${esc(speechProblem)} <button class="text-button" data-action="mic-guide">Help with listening</button></div><div class="button-row compact"><button class="secondary" data-action="hint">Next word</button><button class="secondary" data-action="hear-next">Hear the next verse</button><button class="text-button" data-action="hide">${state.hidden?'Reveal passage':'Hide passage'}</button></div><div id="word-progress" class="small"></div><div id="transcript" class="transcript" lang="ar" dir="rtl" ${latestTranscript?'':'hidden'}>${esc(latestTranscript)}</div><div id="recitation-result"></div><p class="small checking-note">Word matching is experimental and may be wrong. It does not assess tajweed.</p></section>`;}
function setSpeechStatus(message,problem=''){speechStatus=message;speechProblem=problem;const status=$('#listen-status');if(status)status.textContent=message;const issue=$('#speech-problem');if(issue){issue.hidden=!problem;issue.textContent=problem;}const find=$('#find-voice-status');if(find)find.textContent=problem||message;}
function microphoneGuide(){stopListening(false);openModal('Listening on your phone',`<ol class="setup-steps"><li>Open Hifz in <strong>Chrome on Android</strong>, using the menu’s “Open in Chrome” if you came from another app. In-app browsers can block speech recognition.</li><li>Choose <strong>Recite → Start listening</strong>. Allow microphone access when asked.</li><li>Wait until you see <strong>Microphone ready</strong>, then recite Arabic clearly. Keep this page open and your screen awake.</li><li>If denied, open your browser’s site permissions and allow the microphone. Also check Android Settings → Apps → Chrome → Permissions → Microphone.</li><li>Browser recognition needs a working speech service and usually internet. If no words appear, try <strong>Check my microphone</strong> below. iPhone/iPad support varies; recording remains an alternative.</li></ol><p class="small">Browser speech services may process audio remotely. Hifz does not require an API key for browser checking.</p><div class="button-row"><button class="primary" data-action="mic-check">Check my microphone</button><button class="secondary" data-action="typed-check">Compare a transcript</button><button class="secondary" data-action="record">Record myself</button></div>`);}
function weakPractice(){const ids=[...new Set([...Object.entries(state.progress).filter(([,p])=>p.confidence!=='strong').map(([id])=>id),...state.mistakes.map(m=>m.ref),...Object.keys(state.hints)])].filter(id=>{const [s,n]=id.split(':').map(Number);return verseRef(s,n);});if(!ids.length){toast('Mark a verse Needs practice or use a hint first. Your weak verses will appear here.');return;}const [s,n]=ids[Math.floor(Math.random()*ids.length)].split(':').map(Number);state.view='practice';state.mode='recite';state.hidden=true;setSelection(s,n,n);toast('A verse from your weak passages, hints or possible mistakes.');}
function hearNextVerse(){const {refs}=expectedWords();const position=latestAlignment?.position||0;const id=refs[Math.min(position,refs.length-1)];if(!id)return;const [s,n]=id.split(':').map(Number);playQueue([verseRef(s,n)],{single:true});}
function wordsFor(v){return v.text.split(/\s+/).filter(Boolean);}
function versesHTML(){let offset=0;return selected().map(v=>{const words=wordsFor(v),id=ref(v),p=state.progress[id],marked=state.bookmarks.includes(id);const text=words.map((w,k)=>{const norm=normalize(w);const idx=norm?offset++:-1;const matched=latestAlignment?.ops.some(op=>op.index===idx&&op.kind==='match');const show=!state.hidden||idx>=0&&idx<state.hintCount||state.settings.followRecitation&&matched;return `<span class="word${show?'':' hidden-word'}" data-word="${idx}" ${show?'':'aria-label="Hidden word"'}>${show?esc(w):'&#160;&#160;'}</span>`;}).join(' ');return `<article class="verse" data-ref="${id}"><div class="verse-meta"><span>${id}${p?' · '+esc({strong:'Strong',practice:'Needs practice',forgotten:'Revisit'}[p.confidence]||'Practised'):''}</span><div class="row-actions"><button data-play-verse="${v.n}" aria-label="Play verse ${v.n}">${icon('play')}</button><button data-verse-menu="${id}" aria-label="Verse ${v.n} options">${icon(marked?'check':'bookmark')}</button></div></div><div class="arabic" lang="ar" dir="rtl">${text}</div></article>`;}).join('');}
function bindPractice(){$('#surah-select').onchange=e=>setSelection(Number(e.target.value),1,Math.min(3,quran[Number(e.target.value)-1].verses.length));for(const id of ['from-verse','to-verse'])$('#'+id).onchange=()=>setSelection(state.selection.surah,$('#from-verse').value,$('#to-verse').value);}
function reciterName(){return reciters.find(r=>r.id===state.settings.reciter)?.name||'Mishary Alafasy';}
function libraryHTML(){return `<div class="page-heading"><div><div class="eyebrow">114 surahs · 30 juz</div><h1>Your Qur’an.</h1><p class="muted">Find a surah, page or passage to practise.</p></div><div class="button-row"><button class="secondary" data-action="jump">Go to page / juz / verse</button><button class="secondary" data-action="find-verse">Find verse by words</button><button class="secondary" data-action="bookmarks">Bookmarks</button></div></div><input class="search-input" id="surah-search" type="search" placeholder="Search surah name or number" aria-label="Search surahs"><div class="surah-grid" id="surah-grid">${quran.map(s=>`<button class="surah-card" data-open-surah="${s.id}" data-search="${esc((s.id+' '+s.nameEn+' '+s.name+' '+s.meaning).toLowerCase())}"><span class="surah-number">${s.id}</span><span><strong>${esc(s.nameEn)}</strong><small>${s.verses.length} verses${state.settings.memorized.includes(s.id)?' · In your test selection':''}</small></span><span class="name-ar" lang="ar">${esc(s.name)}</span></button>`).join('')}</div>`;}
function searchKey(text){return String(text).toLowerCase().replace(/([a-z])\1+/g,'$1').replace(/[-’']/g,'').trim();}
function filterLibrary(e){const v=searchKey(e.target.value);for(const b of $$('[data-open-surah]'))b.hidden=!searchKey(b.dataset.search).includes(v);}
function revisionHTML(){const entries=state.filter==='mistakes'?state.mistakes.map(x=>[x.ref,x]):Object.entries(state.progress).filter(([,p])=>state.filter==='due'?p.due<=Date.now():p.confidence!=='strong'||state.filter==='all');return `<div class="page-heading"><div><div class="eyebrow">Murājaʿah</div><h1>Keep it close.</h1><p class="muted">Return to the passages that need a little more attention.</p></div><button class="primary" data-action="due-review">Start revision</button></div><div class="tabs">${[['all','All passages'],['due','Due today'],['weak','Needs practice'],['mistakes','Possible mistakes']].map(([f,t])=>`<button data-filter="${f}" class="${state.filter===f?'active':''}">${t}</button>`).join('')}</div><div class="panel">${entries.length?entries.map(([id,p])=>{const [s,n]=id.split(':').map(Number),v=verseRef(s,n);if(!v)return '';return `<div class="review-row"><div><strong>${esc(quran[s-1].nameEn)} · ${id}</strong><div class="small">${state.filter==='mistakes'?esc(p.note||'Possible word difference'):esc({strong:'Strong',practice:'Needs practice',forgotten:'Revisit'}[p.confidence]||'Practised')+' · '+(p.due<=Date.now()?'Due for revision':'Review '+new Date(p.due).toLocaleDateString())}</div>${state.filter==='mistakes'?`<div class="arabic" lang="ar">${esc(v.text)}</div>`:''}</div><div class="row-actions"><button data-review="${id}">Practise</button>${state.filter==='mistakes'?`<button data-dismiss-mistake="${p.id}">Dismiss false alert</button>`:`<button data-verse-menu="${id}">Update confidence</button>`}</div></div>`;}).join(''):`<div class="empty">${icon('repeat')}<h2>${state.filter==='due'?'Nothing due right now':'Your revision starts here'}</h2><p>After practising, mark how confident you feel.<br>We’ll help you decide when to revisit it.</p><button class="primary" data-view="practice">Choose a passage</button></div>`}</div>`;}
function progressHTML(){const strong=Object.values(state.progress).filter(p=>p.confidence==='strong').length;const minutes=Math.round(state.sessions.reduce((sum,x)=>sum+x.seconds,0)/60);const days=new Set(state.sessions.map(x=>x.day));let streak=0,d=new Date();if(!days.has(dateKey(d)))d.setDate(d.getDate()-1);while(days.has(dateKey(d))){streak++;d.setDate(d.getDate()-1);}return `<div class="page-heading"><div><div class="eyebrow">Your journey</div><h1>Every verse matters.</h1><p class="muted">Small, steady steps. Your progress belongs to you.</p></div><button class="secondary" data-action="goal">Set a daily goal</button></div><div class="stats"><div class="stat-card"><div class="stat-value">${strong}</div><div class="stat-label">Verses marked strong</div></div><div class="stat-card"><div class="stat-value">${state.sessions.length}</div><div class="stat-label">Practice sessions</div></div><div class="stat-card"><div class="stat-value">${minutes}</div><div class="stat-label">Minutes practised</div></div><div class="stat-card"><div class="stat-value">${streak}</div><div class="stat-label">Day${streak===1?'':'s'} of consistency</div></div></div><div class="panel"><h2>Your memorization map</h2><p class="small">${strong} of 6,236 verses marked strong. This reflects your own confidence ratings.</p><div class="progress-bar"><span style="width:${strong/6236*100}%"></span></div><button class="secondary" data-action="memorized">Choose memorized surahs for tests</button></div><div class="panel"><h2>A month of showing up</h2><div class="heatmap">${Array.from({length:30},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(29-i));return `<div class="day-cell ${days.has(dateKey(d))?'done':''}" title="${dateKey(d)}${days.has(dateKey(d))?' · Practised':''}"></div>`;}).join('')}</div><p class="small" style="margin:15px 0 0">Daily goal: ${state.settings.goal} ${state.settings.goalUnit}. Missed a day? Simply begin again.</p></div><div class="panel"><h2>Recent sessions</h2>${state.sessions.length?state.sessions.slice(-8).reverse().map(x=>`<div class="review-row"><div><strong>${esc(quran[x.surah-1]?.nameEn||'Qur’an')} · ${x.from}–${x.to}</strong><span class="small">${esc(x.day)} · ${x.seconds?Math.max(1,Math.round(x.seconds/60))+' min · ':''}${esc(x.type)}</span></div><button class="text-button" data-resume="${x.surah}:${x.from}:${x.to}">Practise again</button></div>`).join(''):'<p class="small">Your completed practice sessions will appear here.</p>'}</div><div class="button-row"><button class="secondary" data-action="recordings">My recordings</button><button class="secondary" data-action="hint-history">Passages where I needed hints</button><button class="secondary" data-action="export">Export progress</button></div>`;}
// Playback uses source-provided URLs, including reciters with different audio formats.
let audioMap={};try{audioMap=JSON.parse(localStorage.getItem('hifz.audio.urls')||'{}');}catch{}
async function resolveAudio(v,edition=state.settings.reciter){const k=edition+':'+v.id;if(audioMap[k])return audioMap[k];const res=await fetch(`https://api.alquran.cloud/v1/ayah/${v.id}/${encodeURIComponent(edition)}`);if(!res.ok)throw new Error('Reciter service is unavailable. Try another recording.');const j=await res.json();const url=j.data?.audio;if(!url||!url.startsWith('https://'))throw new Error('This reciter has no recording for the selected verse.');audioMap[k]=url;try{localStorage.setItem('hifz.audio.urls',JSON.stringify(audioMap));}catch{}return url;}
function stopAudio(){chapterPlayback=false;audioGeneration++;clearTimeout(queueTimer);audio.pause();audio.removeAttribute('src');audio.load();if(audioBlobUrl)URL.revokeObjectURL(audioBlobUrl);audioBlobUrl=null;audioQueue=[];queueIndex=0;testAfterAudio=false;$('#player').hidden=true;}
async function playQueue(verses,{single=false,test=false}={}){if(!verses.length)return;if(reciters.find(r=>r.id===state.settings.reciter)?.kind==='surah'){if(test||state.mode!=='read'||single&&verses.length===1){openModal('Verse audio needed',`<p>This qāri has full-surah recordings without verse timings. Choose verse audio for a hint, random prompt or selected-verse repetition.</p><button class="primary wide" data-action="reciter">Choose verse audio</button><button class="secondary wide" data-action="play-chapter">Play this full surah from the beginning</button>`);return;}await playChapter();return;}stopListening(false);stopAudio();testAfterAudio=test;try{audioQueue=single?verses:buildQueue(verses,state.settings.loopStyle,state.settings.repeat,state.settings.cycles);queueIndex=0;await playTrack(audioGeneration);}catch(e){toast(e.message);}}
async function playTrack(gen){if(gen!==audioGeneration||!audioQueue.length)return;const v=audioQueue[queueIndex];$('#player').hidden=false;$('#audio-title').textContent=`${current().nameEn} · Verse ${v.n}`;$('#audio-subtitle').textContent=`${reciterName()} · ${queueIndex+1} / ${audioQueue.length}`;try{const url=await resolveAudio(v);if(gen!==audioGeneration)return;let src=url;if('caches'in window){const c=await caches.open('hifz-audio-v1'),hit=await c.match(url);if(hit){if(audioBlobUrl)URL.revokeObjectURL(audioBlobUrl);src=audioBlobUrl=URL.createObjectURL(await hit.blob());}}if(gen!==audioGeneration)return;audio.src=src;audio.playbackRate=state.settings.speed;await audio.play();$('#audio-toggle').innerHTML=icon('pause');$$('.verse').forEach(e=>e.style.background=e.dataset.ref===`${state.selection.surah}:${v.n}`?'var(--soft)':'');}catch(e){if(gen===audioGeneration)toast('Could not play this recording. Check your connection or choose another qāri.');}}
audio.addEventListener('ended',()=>{if(chapterPlayback){stopAudio();toast('Full surah complete.');return;}if(++queueIndex<audioQueue.length){const g=audioGeneration;queueTimer=setTimeout(()=>playTrack(g),state.settings.pause*1000);}else{const test=testAfterAudio;stopAudio();$$('.verse').forEach(e=>e.style.background='');if(test&&state.quiz){state.selection.from=state.quiz.answer;state.selection.to=Math.min(current().verses.length,state.quiz.answer+state.quiz.length-1);state.hidden=true;state.hintCount=0;render();toast('Your turn. Continue with the next verse. Tap Start listening when ready.');}else toast('Repetition complete. Try reciting without looking.');}});
audio.addEventListener('error',()=>{if(audioQueue.length||chapterPlayback)toast('This recording could not be loaded. Try another qāri.');});
audio.addEventListener('timeupdate',()=>{if(Number.isFinite(audio.duration)&&audio.duration>0)$('#audio-seek').value=audio.currentTime/audio.duration*100;$('#audio-time').textContent=`${Math.floor(audio.currentTime/60)}:${String(Math.floor(audio.currentTime%60)).padStart(2,'0')}`;});
$('#audio-toggle').onclick=()=>{if(audio.paused){audio.play().then(()=>$('#audio-toggle').innerHTML=icon('pause')).catch(()=>toast('Tap play again to resume.'));}else{audio.pause();$('#audio-toggle').innerHTML=icon('play');}};$('#audio-seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(e.target.value)/100;};
async function downloadAudio(){if(reciters.find(r=>r.id===state.settings.reciter)?.kind==='surah'){toast('Offline verse downloads require a verse-audio edition. Choose one in the qāri picker.');return;}if(!('caches'in window)){toast('Offline audio storage is not available in this browser.');return;}const verses=selected();if(verses.length>50){toast('Download up to 50 verses at a time.');return;}openModal('Save audio for offline practice',`<p class="small">Save ${verses.length} verses by ${esc(reciterName())}. Audio uses your device storage. Keep this window open until it finishes.</p><button class="primary wide" id="confirm-download">Download recordings</button><p id="download-status" class="small"></p>`);$('#confirm-download').onclick=async()=>{const btn=$('#confirm-download');btn.disabled=true;let done=0;const c=await caches.open('hifz-audio-v1');for(const v of verses){try{const url=await resolveAudio(v);if(!await c.match(url)){const r=await fetch(url);if(!r.ok||r.type==='opaque')throw new Error();await c.put(url,r);}done++;}catch{}if($('#download-status'))$('#download-status').textContent=`Saved ${done} of ${verses.length} recordings.`;}if(done<verses.length&&$('#download-status'))$('#download-status').textContent+=' Some sources do not permit browser downloads. Streaming may still work.';btn.disabled=false;};}
function reciterPicker(){openModal('Choose your qāri',`<p class="small">${reciters.length} recordings from Al Quran Cloud and MP3Quran. Verse audio supports repetition and prompts. Full-surah audio starts at the beginning and has no verse timing. Some editions use a different riwāyah from this app’s Hafs text.</p><input type="search" id="reciter-search" class="search-input" aria-label="Search reciters" placeholder="Name, Arabic name or recording style"><div class="field-row"><div><label for="reciter-type">Recording type</label><select id="reciter-type"><option value="all">All recordings</option><option value="verse">Verse by verse</option><option value="surah">Full surahs</option></select></div><div><label class="check-row"><input id="reciter-favourites" type="checkbox"> Favourites only</label></div></div><p class="small" id="reciter-count"></p><div class="reciter-list">${reciters.map(r=>`<div class="reciter-entry" data-entry="${esc(r.id)}" data-kind="${r.kind||'verse'}" data-name="${esc((r.name+' '+(r.arabic||'')+' '+(r.style||'')+' '+r.id).toLowerCase())}"><button class="reciter-option ${r.id===state.settings.reciter?'active':''}" data-reciter="${esc(r.id)}">${esc(r.name)}<small>${r.kind==='surah'?'Full surah · MP3Quran':'Verse audio · Al Quran Cloud'}${r.style?' · '+esc(r.style):''}</small><small lang="ar">${esc(r.arabic||'')}</small></button><button class="favourite-button" data-favourite="${esc(r.id)}" aria-label="Favourite ${esc(r.name)}" aria-pressed="${state.settings.favouriteReciters.includes(r.id)}">${state.settings.favouriteReciters.includes(r.id)?'★':'☆'}</button></div>`).join('')}</div>`);for(const id of ['reciter-search','reciter-type','reciter-favourites'])$('#'+id).addEventListener('input',filterReciters);filterReciters();}
function filterReciters(){const query=searchKey($('#reciter-search').value),type=$('#reciter-type').value,favourites=$('#reciter-favourites').checked;let count=0;for(const row of $$('[data-entry]')){row.hidden=!searchKey(row.dataset.name).includes(query)||(type!=='all'&&row.dataset.kind!==type)||(favourites&&!state.settings.favouriteReciters.includes(row.dataset.entry));if(!row.hidden)count++;}$('#reciter-count').textContent=count+' recordings shown';}
async function playChapter(){const r=reciters.find(x=>x.id===state.settings.reciter);if(!r?.surahs?.includes(state.selection.surah)){toast('This recording does not include the selected surah. Choose another qāri.');return;}stopListening(false);stopAudio();chapterPlayback=true;const gen=audioGeneration;$('#player').hidden=false;$('#audio-title').textContent=current().nameEn+' · Full surah';$('#audio-subtitle').textContent=r.name+' · starts at verse 1';audio.src=r.server+String(state.selection.surah).padStart(3,'0')+'.mp3';audio.playbackRate=state.settings.speed;try{await audio.play();if(gen===audioGeneration)$('#audio-toggle').innerHTML=icon('pause');}catch{toast('Full-surah audio could not play. Check your connection or choose another recording.');}}
function playbackSettings(){openModal('Listen & repeat',`<div class="field-group"><label for="loop-style">Repetition pattern</label><select id="loop-style"><option value="verse">Repeat each verse</option><option value="passage">Repeat whole passage</option><option value="connect">Connect verses: 1, then 1–2, then 1–3</option></select></div><div class="field-row"><div><label for="repeat-count">Repeats · 1–100</label><input id="repeat-count" type="number" min="1" max="100" value="${state.settings.repeat}"></div><div><label for="pause-seconds">Pause · seconds</label><input id="pause-seconds" type="number" min="0" max="30" value="${state.settings.pause}"></div></div><div class="field-row" style="margin-top:18px"><div><label for="cycles">Whole cycles · 1–20</label><input id="cycles" type="number" min="1" max="20" value="${state.settings.cycles}"></div><div><label for="audio-speed">Playback speed</label><select id="audio-speed"><option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1">1×</option><option value="1.25">1.25×</option></select></div></div><button class="primary wide" id="save-playback">Save repetition settings</button><button class="secondary wide" data-action="download-audio">Download this passage</button>`);$('#loop-style').value=state.settings.loopStyle;$('#audio-speed').value=state.settings.speed;$('#save-playback').onclick=()=>{state.settings.loopStyle=$('#loop-style').value;state.settings.repeat=clamp($('#repeat-count').value,1,100);state.settings.pause=clamp($('#pause-seconds').value,0,30);state.settings.cycles=clamp($('#cycles').value,1,20);state.settings.speed=Number($('#audio-speed').value);save();closeModal();render();};}
function clamp(value,min,max){return Math.min(max,Math.max(min,Math.round(Number(value)||min)));}
function markConfidence(id,confidence){const old=state.progress[id],review=nextReview(confidence,old?.interval||0);state.progress[id]={confidence,due:review.due,interval:review.days,updated:Date.now()};save();}
function addSession(type,seconds){state.sessions.push({id:Date.now(),day:dateKey(),surah:state.selection.surah,from:state.selection.from,to:state.selection.to,type,seconds:Math.max(0,Math.min(7200,Math.round(Number.isFinite(seconds)?seconds:0)))});save();}
function verseMenu(id){const [s,n]=id.split(':').map(Number),v=verseRef(s,n);if(!v)return;openModal(`${quran[s-1].nameEn} · ${id}`,`<div class="arabic" lang="ar">${esc(v.text)}</div><p class="small">How confident do you feel with this verse?</p><div class="confidence-row">${[['strong','Strong'],['practice','Needs practice'],['forgotten','Forgotten']].map(([c,t])=>`<button data-confidence="${c}" data-id="${id}" class="${state.progress[id]?.confidence===c?'active':''}">${t}</button>`).join('')}</div><div class="button-row"><button class="secondary" data-bookmark="${id}">${state.bookmarks.includes(id)?'Remove bookmark':'Bookmark verse'}</button><button class="secondary" data-manual-mistake="${id}">Add a mistake note</button><button class="secondary" data-similar="${id}">Compare similar verses</button></div><p class="small" style="margin-top:18px">${n>1?'Previous verse: '+esc(verseRef(s,n-1).text):'Beginning of the surah.'}</p>`);}
function similarVerses(id){const [s,n]=id.split(':').map(Number),v=verseRef(s,n),words=tokenize(v.text);const prefix=words.slice(0,Math.min(3,words.length)).join(' ');const hits=[];for(const surah of quran)for(const ayah of surah.verses){if(surah.id===s&&ayah.n===n)continue;if(normalize(ayah.text).startsWith(prefix))hits.push({s:surah.id,v:ayah});if(hits.length>=25)break;}openModal('Compare similar openings',`<p class="small">Verses sharing the first ${Math.min(3,words.length)} normalized words. This does not cover every type of similar verse.</p><div class="arabic" lang="ar">${esc(v.text)}</div>${hits.length?hits.slice(0,25).map(x=>`<div class="review-row"><div><strong>${esc(quran[x.s-1].nameEn)} · ${x.s}:${x.v.n}</strong><div class="arabic" lang="ar">${esc(x.v.text)}</div></div><button class="secondary" data-review="${x.s}:${x.v.n}">Practise</button></div>`).join(''):'<p class="small">No other verse has this exact opening.</p>'}`);}
function addMistake(id,note,auto=false){if(auto&&state.mistakes.some(x=>x.ref===id&&x.note===note&&Date.now()-x.created<3600000))return;state.mistakes.push({id:`m${Date.now()}-${Math.random().toString(16).slice(2,7)}`,ref:id,note,created:Date.now(),auto});markConfidence(id,'practice');save();}
function hint(){state.hintCount+=state.hintCount===0?1:3;state.hidden=true;for(const v of selected()){const id=ref(v);state.hints[id]=(state.hints[id]||0)+1;}save();$('#verses').innerHTML=versesHTML();updateRecitation();toast('A little help is part of learning. Tap again for more words.');}
function memorizedPicker(){openModal('What have you memorized?',`<p class="small">Choose surahs for random tests. For a partial surah, use a custom test range.</p><input class="search-input" id="memorized-search" type="search" placeholder="Find a surah" aria-label="Find memorized surah"><div class="reciter-list">${quran.map(s=>`<label class="check-row" data-search="${esc((s.id+' '+s.nameEn).toLowerCase())}"><input type="checkbox" data-memorized="${s.id}" ${state.settings.memorized.includes(s.id)?'checked':''}>${s.id}. ${esc(s.nameEn)}</label>`).join('')}</div><button class="primary wide" id="save-memorized">Save test selection</button>`);$('#memorized-search').oninput=e=>{for(const row of $$('[data-search]',$('#modal')))row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase());};$('#save-memorized').onclick=()=>{state.settings.memorized=$$('[data-memorized]:checked').map(e=>Number(e.dataset.memorized));save();closeModal();render();};}
let testRange=null;
function quizOptions(){openModal('Choose your test',`<div class="field-group"><label for="test-surah">Surah</label><select id="test-surah">${quran.map(s=>`<option value="${s.id}" ${s.id===state.selection.surah?'selected':''}>${s.id}. ${esc(s.nameEn)}</option>`).join('')}</select></div><div class="field-row"><div><label for="test-from">From verse</label><input id="test-from" type="number" min="1" value="${state.selection.from}"></div><div><label for="test-to">To verse</label><input id="test-to" type="number" min="1" value="${state.selection.to}"></div></div><div class="field-group"><label for="question-length">Continue for how many verses?</label><input id="question-length" type="number" min="1" max="10" value="2"></div><button class="primary wide" id="begin-custom-test">Begin test</button><button class="secondary wide" data-action="memorized">Choose memorized surahs instead</button>`);$('#test-surah').onchange=e=>{$('#test-from').value=1;$('#test-to').value=quran[Number(e.target.value)-1].verses.length;};$('#begin-custom-test').onclick=()=>{const s=Number($('#test-surah').value),count=quran[s-1].verses.length,from=clamp($('#test-from').value,1,count),to=clamp($('#test-to').value,from,count);testRange={s,from,to,length:clamp($('#question-length').value,1,10)};closeModal();quiz();};}
function quiz(){if(listening)stopListening(false);const candidates=testRange?[testRange.s]:state.settings.memorized;if(!candidates.length){memorizedPicker();return;}const s=candidates[Math.floor(Math.random()*candidates.length)],count=quran[s-1].verses.length;let from=testRange?.from||1,to=testRange?.to||count;if(to<=from){toast('Choose at least two verses so there is a verse to continue.');return;}const prompt=from+Math.floor(Math.random()*(to-from));setSelection(s,prompt,prompt);state.mode='test';state.hidden=false;state.quiz={prompt,answer:prompt+1,length:Math.min(testRange?.length||2,to-prompt)};render();playQueue(selected(),{single:true,test:true});}
function nextPassage(direction){const len=state.selection.to-state.selection.from+1;let from=state.selection.from+len*direction,s=state.selection.surah;if(from>current().verses.length){s=Math.min(114,s+1);from=1;}if(from<1){s=Math.max(1,s-1);from=Math.max(1,quran[s-1].verses.length-len+1);}setSelection(s,from,Math.min(from+len-1,quran[s-1].verses.length));}
function jumpDialog(){openModal('Go to a passage',`<div class="field-group"><label for="jump-kind">Find by</label><select id="jump-kind"><option value="page">Madinah page · 1–604</option><option value="juz">Juz · 1–30</option><option value="verse">Verse reference · e.g. 2:255</option></select></div><input id="jump-value" class="search-input" placeholder="Enter page number" aria-label="Page, juz or verse reference"><button class="primary wide" id="jump-go">Open passage</button>`);$('#jump-kind').onchange=()=>$('#jump-value').placeholder=$('#jump-kind').value==='verse'?'2:255':'Enter number';$('#jump-go').onclick=()=>{const kind=$('#jump-kind').value,value=$('#jump-value').value.trim();if(kind==='verse'){const a=value.split(':').map(Number);if(!verseRef(a[0],a[1])){toast('Enter a valid verse reference.');return;}closeModal();state.view='practice';setSelection(a[0],a[1],a[1]);}else{const num=Number(value);if(!Number.isInteger(num)||num<1||num>(kind==='page'?604:30)){toast('Enter a valid '+kind+' number.');return;}for(const s of quran){const found=s.verses.filter(v=>v[kind]===num);if(found.length){closeModal();state.view='practice';setSelection(s.id,found[0].n,found[found.length-1].n);return;}}}};}
function expectedWords(){let words=[],refs=[];for(const v of selected())for(const w of tokenize(v.text)){words.push(canonicalQuranWord(w));refs.push(ref(v));}return {words,refs};}
function updateRecitation(){if(!latestAlignment||state.view!=='practice')return;const verses=$('#verses');if(verses){verses.innerHTML=versesHTML();hydrateIcons();}for(const op of latestAlignment.ops){const el=$(`[data-word="${op.index}"]`);if(el){if(op.kind==='match')el.classList.add('correct');else if(!listening||state.settings.feedback==='live')el.classList.add('possible');}}if($('#transcript')){$('#transcript').textContent=latestTranscript;$('#transcript').hidden=!latestTranscript;}if($('#word-progress'))$('#word-progress').textContent=`${latestAlignment.matches} matched · ${latestAlignment.remaining} words not checked`;}
function compareTranscript(text,{finish=false}={}){latestTranscript=text;const expected=expectedWords();try{latestAlignment=alignWords(expected.words,tokenize(text));updateRecitation();if(finish){const a=latestAlignment;for(const op of a.differences){const id=expected.refs[op.index];if(id)addMistake(id,op.kind==='missing'?`Possible missed word: ${op.expected}`:op.kind==='extra'?`Possible added word: ${op.heard}`:`Possible changed word: ${op.expected} / recognized ${op.heard}`,true);}if($('#recitation-result'))$('#recitation-result').innerHTML=`<div class="inline-result"><strong>${a.matches} matched words</strong><br>${a.differences.length} possible differences · ${a.remaining} words not checked.<p class="small">Recognition may be wrong. Replay the verse and dismiss false alerts in Revision.</p>${a.differences.slice(0,12).map(op=>`<div class="difference-row"><span>${esc(expected.refs[op.index]||'')} · Expected <b lang="ar">${esc(op.expected||'—')}</b> · Recognized <b lang="ar">${esc(op.heard||'—')}</b></span><button class="secondary" data-review-audio="${esc(expected.refs[op.index]||'')}">Replay verse</button></div>`).join('')}<div class="button-row"><button class="secondary" data-action="retry">Try again</button><button class="secondary" data-action="correct-audio">Hear the correction</button><button class="secondary" data-action="weak-practice">Practise weak verses</button></div></div>`;}}catch(e){toast(e.message);}}
function speechSupported(){return Boolean(window.SpeechRecognition||window.webkitSpeechRecognition);}
function speechUnavailable(){openModal('Speech checking in this browser',`<p>This browser does not offer live speech recognition.</p><p class="small">On Android, open this page in Chrome rather than an in-app browser. You can still listen, repeat and record yourself without a key.</p><div class="button-row"><button class="primary" data-action="mic-guide">Phone setup guide</button><button class="secondary" data-action="record">Record myself</button><button class="secondary" data-action="typed-check">Compare a transcript</button><button class="secondary" data-action="speech-settings">Optional cloud transcription</button></div>`);}
async function startListening(){if(listening){stopListening(true);return;}if(finishing)return;if(expectedWords().words.length>1200){setSpeechStatus('Choose a shorter passage.','Live checking supports up to 1,200 words.');return;}if(state.settings.speechMode==='cloud'){if(!apiKey){settingsDialog('speech');toast('Cloud transcription needs your own key. Choose Browser speech recognition to check without a key where supported.');return;}openModal('Record for transcription',`<p class="small">Your audio will be sent to ${esc(new URL(state.settings.cloudEndpoint).hostname)} using your own API key. Provider limits and billing apply. This compares words, not tajweed.</p><button class="primary wide" id="cloud-record-start">Start recording for transcription</button>`);$('#cloud-record-start').onclick=()=>{closeModal();startRecording(true);};return;}if(!speechSupported()){speechUnavailable();return;}stopAudio();if(recording)await stopRecording();findingPassage=false;beginSpeech();render();}
function beginSpeech(){stopListening(false);latestTranscript='';latestAlignment=null;heardBase='';recognitionErrors=0;sessionStarted=Date.now();listening=true;stopping=false;finishing=false;setSpeechStatus('Starting microphone… Allow access if your browser asks.');startBrowserRecognizer();}
function showSpeechError(code){const messages={'not-allowed':'Microphone permission was denied. Allow it in your browser and phone settings.','service-not-allowed':'This browser or speech service blocked recognition. Open the page in Chrome on Android.','audio-capture':'No microphone was available. Check your microphone permissions and disconnect competing recording apps.','language-not-supported':'The speech service does not support Arabic on this device.','network':'The speech service could not connect. Check internet access or try another browser.','no-speech':'No words were recognized. Speak clearly after Microphone ready; check the microphone if this repeats.','aborted':'Listening was interrupted. Tap Start listening to try again.'};listening=false;finishing=false;clearTimeout(speechTimer);clearTimeout(restartTimer);clearTimeout(finishTimer);setSpeechStatus('Listening stopped.',messages[code]||'Speech recognition could not continue. Try the microphone check or record yourself.');if(state.view==='practice'&&!findingPassage){render();updateRecitation();}else if($('#find-voice-toggle'))$('#find-voice-toggle').textContent='Try listening again';}
function startBrowserRecognizer(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;recognition=new Speech();recognition.lang='ar-SA';recognition.continuous=true;recognition.interimResults=true;recognition.maxAlternatives=1;const activeRecognizer=recognition;let currentFinal='';
 recognition.onstart=()=>{if(recognition!==activeRecognizer)return;setSpeechStatus('Microphone ready. Recite your passage now.');clearTimeout(speechTimer);speechTimer=setTimeout(()=>{if(listening&&!latestTranscript)setSpeechStatus('No recognized words yet.','If you are speaking, open Phone setup or Check my microphone. In-app browsers may not support the speech service.');},9000);};
 recognition.onspeechstart=()=>{if(recognition===activeRecognizer)setSpeechStatus('Hearing speech… waiting for recognized Arabic words.');};
 recognition.onresult=e=>{if((!listening&&!finishing)||recognition!==activeRecognizer)return;let final='',interim='';for(let i=0;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)final+=t+' ';else interim+=t+' ';}currentFinal=final.trim();const text=(heardBase+' '+final+' '+interim).trim();clearTimeout(speechTimer);setSpeechStatus('Receiving Arabic words. Matched words are highlighted.');if(findingPassage){latestTranscript=text;updateVoiceCandidates(text);}else compareTranscript(text);};
 recognition.onerror=e=>{if(recognition!==activeRecognizer)return;recognitionErrors++;if(finishing&&e.error==='no-speech'){finishSpeech();return;}if(['not-allowed','service-not-allowed','audio-capture','language-not-supported','network'].includes(e.error)||recognitionErrors>=3){showSpeechError(e.error);recognition=null;try{activeRecognizer.abort();}catch{}}else setSpeechStatus('No recognized words yet. Keep reciting clearly.');};
 recognition.onend=()=>{if(recognition!==activeRecognizer)return;recognition=null;if(currentFinal)heardBase=(heardBase+' '+currentFinal).trim();if(finishing){finishSpeech();return;}if(listening&&!stopping){setSpeechStatus('Reconnecting to speech recognition…');restartTimer=setTimeout(()=>{if(listening)startBrowserRecognizer();},450);}};
 try{recognition.start();clearTimeout(speechTimer);speechTimer=setTimeout(()=>{if(listening&&!latestTranscript)setSpeechStatus('Still waiting for speech recognition.','Allow microphone access, or open this page in Chrome. The browser may not provide a working speech service.');},9000);}catch{recognition=null;showSpeechError('aborted');}}
function finishSpeech(){const wasFinding=findingPassage;clearTimeout(finishTimer);clearTimeout(speechTimer);finishing=false;listening=false;stopping=true;recognition=null;setSpeechStatus(latestTranscript?'Recitation finished. Review the words below.':'No words were recognized.','');if(wasFinding){updateVoiceCandidates(latestTranscript);if($('#find-voice-toggle'))$('#find-voice-toggle').textContent='Listen again';return;}render();if(latestTranscript.trim()){compareTranscript(latestTranscript,{finish:true});addSession('Recitation',Math.round((Date.now()-sessionStarted)/1000));}else setSpeechStatus('No words were recognized.','Try Check my microphone and open this page in Chrome on Android.');}
function stopListening(saveSession=false){clearTimeout(restartTimer);clearTimeout(speechTimer);const active=recognition,was=listening;listening=false;stopping=true;if(was&&saveSession&&active){finishing=true;setSpeechStatus('Finishing your recitation…');if($('#listen-button')){$('#listen-button').disabled=true;$('#listen-button').textContent='Finishing…';}try{active.stop();}catch{finishSpeech();}finishTimer=setTimeout(()=>{if(finishing){try{active.abort();}catch{}finishSpeech();}},1400);return;}clearTimeout(finishTimer);finishing=false;recognition=null;if(active)try{active.abort();}catch{}if($('#listen-button')){$('#listen-button').disabled=false;$('#listen-button').innerHTML=icon('mic')+'Start listening';}if(was)setSpeechStatus('Listening stopped. Tap Start listening to resume.');}
function findByVoice(){stopListening(false);findingPassage=true;openModal('Find my passage by voice',`<p class="small">Tap Listen, allow the microphone and recite at least four Arabic words. Choose the suggested verse; shared phrases may have several matches. This uses your browser’s speech service.</p><button class="primary wide" id="find-voice-toggle">Listen for my passage</button><p id="find-voice-status" role="status" aria-live="polite">Ready when you are.</p><div id="find-voice-transcript" class="arabic" dir="rtl" lang="ar"></div><div id="voice-candidates"></div><button class="text-button" data-action="find-verse">Type words instead</button>`);$('#find-voice-toggle').onclick=()=>{if(listening){stopListening(true);return;}if(!speechSupported()){speechUnavailable();return;}findingPassage=true;beginSpeech();$('#find-voice-toggle').textContent='Finish listening';};}
function updateVoiceCandidates(text){if(!$('#voice-candidates'))return;$('#find-voice-transcript').textContent=text;const result=locatePassage(quran,text);$('#voice-candidates').innerHTML=`<p class="small">${esc(result.reason)}</p>`+result.candidates.map(x=>`<button class="secondary wide" data-review="${x.surah}:${x.verse}">${esc(quran[x.surah-1].nameEn)} · ${x.surah}:${x.verse}</button>`).join('');}
function typedCheck(){openModal('Compare a transcript',`<p class="small">Paste recognized Arabic or type what you recited. This compares words only; it does not listen to your voice.</p><textarea id="typed-transcript" lang="ar" dir="rtl" aria-label="Arabic transcript" placeholder="اكتب الكلمات هنا"></textarea><button class="primary wide" id="compare-typed">Compare with my selected passage</button>`);$('#compare-typed').onclick=()=>{const t=$('#typed-transcript').value;if(!normalize(t)){toast('Enter some Arabic words first.');return;}closeModal();state.mode='recite';state.view='practice';render();compareTranscript(t,{finish:true});};}
async function startRecording(cloud=false){if(recording){await stopRecording();return;}stopListening(false);stopAudio();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable in this browser.');return;}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(x=>MediaRecorder.isTypeSupported(x));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});recordChunks=[];const capturedChunks=recordChunks;sessionStarted=Date.now();recording=true;recorder.ondataavailable=e=>{if(e.data.size)capturedChunks.push(e.data);};const capturedSelection={...state.selection},capturedRecorder=recorder;recorder.onstop=async()=>{const blob=new Blob(capturedChunks,{type:capturedRecorder.mimeType||'audio/webm'});if(cloud)await transcribe(blob,capturedSelection);else if(blob.size){try{const id=Date.now(),record={id,surah:capturedSelection.surah,from:capturedSelection.from,to:capturedSelection.to,date:new Date().toISOString(),blob};if(state.guest){toast('Guest recording finished. Export it now if you want to keep it.');recordings.unshift(record);}else if(db){await dbRequest('recordings','readwrite',s=>s.put(record));recordings.unshift(record);}else{recordings.unshift(record);toast('Recording is available this session only. Download it to keep it.');}recordingsDialog();}catch{toast('Could not store this recording. Device storage may be full.');}}};recorder.start();toast('Recording started. Tap Record myself again to stop.');render();const btn=$('[data-action="record"]');if(btn)btn.classList.add('recording-active');if(cloud){openModal('Recording your recitation',`<div class="listening-status recording-active"><span class="listening-dot"></span>Recording audio for your chosen provider.</div><button class="primary wide" id="cloud-stop">Stop & transcribe</button><p class="small">Keep the page open. Audio is sent only when you stop.</p>`);$('#cloud-stop').onclick=async()=>{closeModal();await stopRecording();};}}catch{recording=false;stopTracks();toast('Microphone access was denied or unavailable.');}}
function stopTracks(){if(recordStream)recordStream.getTracks().forEach(t=>t.stop());recordStream=null;}
async function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();recording=false;stopTracks();if(state.view==='practice')render();}
async function transcribe(blob,capturedSelection){if(blob.size>20*1024*1024){toast('Recording is too large. Use a shorter passage.');return;}toast('Transcribing with your selected provider…');try{const form=new FormData();const ext=blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm';form.append('file',blob,'recitation.'+ext);form.append('model',state.settings.cloudModel);form.append('language','ar');const res=await fetch(state.settings.cloudEndpoint,{method:'POST',headers:{Authorization:'Bearer '+apiKey},body:form,redirect:'error'});if(!res.ok)throw new Error(res.status===429?'Provider quota reached. Listening and recording still work.':'Transcription failed. Check your key and model.');const j=await res.json();if(JSON.stringify(capturedSelection)!==JSON.stringify(state.selection)){toast('The passage changed during transcription. Select the original passage and try again.');return;}if(!j.text)throw new Error('No speech was returned. Try a clearer recording.');state.mode='recite';state.view='practice';render();compareTranscript(j.text,{finish:true});addSession('Recorded word check',Math.round((Date.now()-sessionStarted)/1000));}catch(e){toast(e.message||'Cloud transcription is unavailable.');}}
async function microphoneCheck(){if(!navigator.mediaDevices?.getUserMedia){toast('Microphone testing is unavailable.');return;}openModal('Microphone check',`<p>Speak normally and watch the level.</p><div class="progress-bar" style="height:16px"><span id="mic-level" style="width:0%"></span></div><p id="mic-advice" class="small">Waiting for microphone permission…</p><p class="small">This test does not save a recording or send audio from this page.</p>`);try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),ctx=new (window.AudioContext||window.webkitAudioContext)(),analyser=ctx.createAnalyser(),source=ctx.createMediaStreamSource(stream);source.connect(analyser);analyser.fftSize=512;const data=new Uint8Array(analyser.fftSize);let frame;const tick=()=>{analyser.getByteTimeDomainData(data);let sum=0;for(const x of data)sum+=((x-128)/128)**2;const level=Math.min(100,Math.sqrt(sum/data.length)*500);if($('#mic-level'))$('#mic-level').style.width=level+'%';if($('#mic-advice'))$('#mic-advice').textContent=level>8?'Your voice is reaching the microphone.':'Speak a little closer, or check your microphone.';frame=requestAnimationFrame(tick);};tick();micCleanup=()=>{cancelAnimationFrame(frame);stream.getTracks().forEach(t=>t.stop());ctx.close();};if(!$('#modal').open)stopMicCheck();}catch{if($('#mic-advice'))$('#mic-advice').textContent='Microphone access was denied or unavailable.';}}
function stopMicCheck(){if(micCleanup){micCleanup();micCleanup=null;}}
async function openDB(){return new Promise((resolve)=>{if(!window.indexedDB){resolve(null);return;}const request=indexedDB.open('hifz-local',1);request.onupgradeneeded=()=>request.result.createObjectStore('recordings',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);});}
function dbRequest(name,mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(name,mode),r=fn(tx.objectStore(name));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
let recordingUrls=[];
function recordingsDialog(){for(const u of recordingUrls)URL.revokeObjectURL(u);recordingUrls=[];openModal('My recordings',`<p class="small">Recordings are stored on this device only. They are not uploaded unless you explicitly choose cloud transcription. Keep a backup before clearing browser data.</p><div class="record-list">${recordings.length?recordings.map(r=>{const u=URL.createObjectURL(r.blob);recordingUrls.push(u);return `<div class="review-row"><div style="width:100%"><strong>${esc(quran[r.surah-1]?.nameEn||'Qur’an')} · ${r.from}–${r.to}</strong><span class="small">${new Date(r.date).toLocaleString()}</span><audio controls src="${u}"></audio><div class="button-row"><a class="secondary" href="${u}" download="Hifz-${r.surah}-${r.from}-${r.id}.${r.blob.type.includes('mp4')?'m4a':'webm'}">Download / share with teacher</a><button class="secondary" data-record-compare="${r.surah}:${r.from}:${r.to}">Hear qāri for this passage</button><button class="text-button danger" data-delete-record="${r.id}">Delete recording</button></div></div></div>`;}).join(''):'<div class="empty"><h2>No recordings yet</h2><p>Use Record myself in your practice panel.</p></div>'}</div>`);}
function settingsDialog(section=''){openModal('Make Hifz yours',`
<h3>Reading & appearance</h3><div class="setting-row"><label for="theme-setting">Theme</label><select id="theme-setting"><option value="light">Warm ivory</option><option value="dark">Evening green</option></select></div><div class="setting-row"><label for="font-size">Arabic text size</label><input id="font-size" type="range" min="26" max="56" value="${state.settings.fontSize}"></div><div class="button-row"><button class="secondary" data-action="reciter">Choose qāri</button><button class="secondary" data-action="playback-settings">Repetition settings</button></div>
<div class="settings-section"><h3>Memorization & revision</h3><div class="button-row"><button class="secondary" data-action="memorized">My memorized surahs</button><button class="secondary" data-action="goal">Daily goal</button></div><label class="check-row"><input id="review-first" type="checkbox" ${state.settings.reviewFirst?'checked':''}>Remind me to review before new memorization</label></div>
<div class="settings-section" id="speech-settings"><h3>Recitation checking</h3><label class="check-row"><input id="follow-recitation" type="checkbox" ${state.settings.followRecitation?'checked':''}>Reveal matched words as I recite</label><button class="secondary" data-action="mic-guide">Phone setup guide</button><p class="small">Browser checking needs no API key but depends on your browser’s speech service and may need internet. It may process audio remotely. Hifz compares recognized words; it does not assess tajweed.</p><div class="setting-row"><label for="feedback-setting">Show possible differences</label><select id="feedback-setting"><option value="after">After I finish</option><option value="live">During recitation</option></select></div><div class="setting-row"><label for="speech-mode">Speech method</label><select id="speech-mode"><option value="browser">Browser speech recognition</option><option value="cloud">Record & transcribe with my provider</option></select></div><details ${section==='speech'?'open':''}><summary>Optional cloud transcription</summary><p class="small">Audio is sent only after you confirm recording for transcription. Your key stays in memory for this visit and is excluded from backups. A provider’s free tier can have limits; Hifz cannot guarantee zero charges on a billing-enabled account.</p><div class="field-group"><label for="cloud-endpoint">OpenAI-compatible HTTPS transcription endpoint</label><input id="cloud-endpoint" type="url" style="width:100%" value="${esc(state.settings.cloudEndpoint)}"></div><div class="field-group"><label for="cloud-model">Transcription model</label><input id="cloud-model" style="width:100%" value="${esc(state.settings.cloudModel)}"></div><div class="field-group"><label for="cloud-key">Your API key · optional</label><input id="cloud-key" type="password" autocomplete="off" style="width:100%" placeholder="Enter key for this visit only"></div><a href="https://console.groq.com/keys" target="_blank" rel="noopener noreferrer">Get your own Groq key</a><button class="text-button" id="remove-key">Forget key for this visit</button></details></div>
<div class="settings-section"><h3>Privacy & your data</h3><p class="small">Progress and recordings stay in this browser. They do not automatically sync between devices. Export progress to move it to another device. Download recordings separately.</p><label class="check-row"><input id="guest-toggle" type="checkbox" ${state.guest?'checked':''}>Guest mode · don’t change my saved progress</label><div class="button-row"><button class="secondary" data-action="export">Export progress</button><button class="secondary" data-action="import">Restore progress</button><button class="secondary" data-action="recordings">My recordings</button><button class="secondary" data-action="audio-manager">Downloaded audio</button></div><button class="text-button danger" data-action="clear-progress">Clear saved progress</button></div><button class="primary wide" id="save-settings">Save settings</button><p class="small" style="margin-top:15px">Hifz 1.1 · Hafs text · Local progress · No account required</p>`);
 $('#theme-setting').value=state.settings.theme;$('#feedback-setting').value=state.settings.feedback;$('#speech-mode').value=state.settings.speechMode;
 $('#remove-key').onclick=()=>{apiKey='';$('#cloud-key').value='';toast('API key forgotten.');};
 $('#save-settings').onclick=()=>{let url;try{url=new URL($('#cloud-endpoint').value);if(url.protocol!=='https:')throw new Error();}catch{toast('Use a valid HTTPS transcription endpoint.');return;}state.settings.theme=$('#theme-setting').value;state.settings.fontSize=clamp($('#font-size').value,26,56);state.settings.followRecitation=$('#follow-recitation').checked;state.settings.feedback=$('#feedback-setting').value;state.settings.speechMode=$('#speech-mode').value;state.settings.cloudEndpoint=url.href;state.settings.cloudModel=$('#cloud-model').value.trim();if($('#cloud-key').value.trim())apiKey=$('#cloud-key').value.trim();state.settings.reviewFirst=$('#review-first').checked;const guest=$('#guest-toggle').checked;closeModal();toggleGuest(guest).then(()=>{save();render();toast('Settings saved.');});};}
let guestSnapshot=null;
async function toggleGuest(value){if(value===state.guest)return;if(listening)stopListening(false);if(recording)await stopRecording();if(value){guestSnapshot=JSON.parse(JSON.stringify({settings:state.settings,progress:state.progress,mistakes:state.mistakes,hints:state.hints,sessions:state.sessions,bookmarks:state.bookmarks,selection:state.selection}));state.progress={};state.mistakes=[];state.hints={};state.sessions=[];state.bookmarks=[];state.guest=true;}else{if(guestSnapshot)Object.assign(state,guestSnapshot);guestSnapshot=null;state.guest=false;if(db)recordings=(await dbRequest('recordings','readonly',s=>s.getAll())).reverse();}render();}
function goalDialog(){openModal('Your daily goal',`<p class="small">Choose something you can return to comfortably. Goals guide you; they don’t measure recitation quality.</p><div class="field-row"><div><label for="goal-value">Amount</label><input id="goal-value" type="number" min="1" max="200" value="${state.settings.goal}"></div><div><label for="goal-unit">Measure</label><select id="goal-unit"><option value="minutes">Minutes</option><option value="verses">Verses</option><option value="pages">Pages</option></select></div></div><button class="primary wide" id="save-goal">Save goal</button>`);$('#goal-unit').value=state.settings.goalUnit;$('#save-goal').onclick=()=>{state.settings.goal=clamp($('#goal-value').value,1,200);state.settings.goalUnit=$('#goal-unit').value;save();closeModal();render();};}
function exportProgress(){const data={app:'Hifz',version:1,exported:new Date().toISOString(),settings:state.settings,progress:state.progress,mistakes:state.mistakes,hints:state.hints,sessions:state.sessions,bookmarks:state.bookmarks,selection:state.selection};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`Hifz-progress-${dateKey()}.json`);toast('Progress exported. Recordings and API keys are not included.');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function importProgress(){openModal('Restore progress',`<p class="small">Restore a Hifz JSON backup. This replaces progress on this device. Recordings are kept separately.</p><input id="backup-file" type="file" accept="application/json,.json" aria-label="Choose Hifz backup"><div id="backup-preview"></div>`);$('#backup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>3000000)throw new Error();const b=JSON.parse(await f.text());if(b.app!=='Hifz'||b.version!==1||!Array.isArray(b.sessions)||typeof b.progress!=='object'||!b.settings)throw new Error();$('#backup-preview').innerHTML=`<p class="small">${b.sessions.length} sessions · ${Object.keys(b.progress).length} practised verses</p><button class="primary wide" id="confirm-restore">Replace progress with this backup</button>`;$('#confirm-restore').onclick=()=>{const cleanProgress={};for(const [id,p]of Object.entries(b.progress)){const [s,n]=id.split(':').map(Number);if(verseRef(s,n)&&['strong','practice','forgotten'].includes(p.confidence)&&Number.isFinite(p.due))cleanProgress[id]={confidence:p.confidence,due:p.due,interval:clamp(p.interval,0,30),updated:Number(p.updated)||Date.now()};}state.progress=cleanProgress;state.sessions=b.sessions.filter(x=>verseRef(Number(x.surah),Number(x.from))&&verseRef(Number(x.surah),Number(x.to))&&typeof x.day==='string'&&Number.isFinite(x.seconds)).slice(-200);state.mistakes=Array.isArray(b.mistakes)?b.mistakes.filter(x=>typeof x.ref==='string'&&typeof x.note==='string').slice(-500):[];state.hints=b.hints&&typeof b.hints==='object'?b.hints:{};state.bookmarks=Array.isArray(b.bookmarks)?b.bookmarks.filter(id=>{const a=String(id).split(':').map(Number);return Boolean(verseRef(a[0],a[1]));}):[];state.settings.theme=['light','dark'].includes(b.settings.theme)?b.settings.theme:'light';state.settings.fontSize=clamp(b.settings.fontSize||34,26,56);state.settings.memorized=Array.isArray(b.settings.memorized)?b.settings.memorized.filter(x=>Number.isInteger(x)&&x>=1&&x<=114):defaults.memorized;state.settings.favouriteReciters=Array.isArray(b.settings.favouriteReciters)?b.settings.favouriteReciters.filter(id=>reciters.some(r=>r.id===id)):[];state.settings.reciter=reciters.some(r=>r.id===b.settings.reciter)?b.settings.reciter:defaults.reciter;state.settings.repeat=clamp(b.settings.repeat||3,1,100);state.settings.pause=clamp(b.settings.pause||2,0,30);state.settings.goal=clamp(b.settings.goal||10,1,200);state.settings.goalUnit=['minutes','verses','pages'].includes(b.settings.goalUnit)?b.settings.goalUnit:'minutes';save();closeModal();render();toast('Progress restored.');};}catch{toast('That is not a valid Hifz backup.');}};}
async function audioManager(){if(!('caches'in window)){toast('Offline audio storage is unavailable.');return;}const c=await caches.open('hifz-audio-v1'),keys=await c.keys();let total=0;for(const key of keys){const r=await c.match(key);total+=(await r.blob()).size;}openModal('Downloaded audio',`<p>${keys.length} recordings · ${(total/1048576).toFixed(1)} MB</p><p class="small">Select a passage and use repetition settings to download it. Some reciter sources do not support browser downloads. Browser storage may be cleared by your device.</p><button class="secondary wide" data-action="download-audio">Download current passage</button><button class="text-button danger" id="clear-audio">Remove downloaded audio</button>`);$('#clear-audio').onclick=()=>openModal('Remove downloaded audio?',`<p>This removes offline recordings. You can download them again later.</p><button class="primary wide" id="confirm-clear-audio">Remove downloaded audio</button>`);$('#modal-body').addEventListener('click',async e=>{if(e.target.id==='confirm-clear-audio'){await caches.delete('hifz-audio-v1');closeModal();toast('Downloaded audio removed.');}},{once:false});}
function help(){openModal('A simple way to practise',`<h3>1. Choose a small passage</h3><p class="small">Open a surah in Qur’an, or select one in your practice panel.</p><h3>2. Listen, repeat, connect</h3><p class="small">Use Memorize mode. Pick a qāri and adjust repetition. Connect verses when each verse feels familiar.</p><h3>3. Hide and recite</h3><p class="small">Tap Start listening above the verses, allow the microphone and wait for Microphone ready. Recite mode alone does not activate listening. On Android, use Chrome rather than an in-app browser.</p><p class="small">Recite mode compares recognized Arabic with your passage. Possible differences need your review. If the browser cannot recognize speech, record yourself or use optional transcription.</p><h3>4. Return tomorrow</h3><p class="small">Mark confidence after practice. Strong verses are scheduled further apart; weaker passages return sooner.</p><h3>Install on your device</h3><p class="small">Android: use your browser’s Install app or Add to Home screen option. iPhone/iPad: open in Safari, tap Share, then Add to Home Screen. Keep the app open for microphone sessions.</p><h3>Your privacy</h3><p class="small">Progress is local. Browser speech services may process audio remotely. Record myself saves locally; optional cloud transcription sends audio only after confirmation. Export before clearing browser data.</p>`);}
function manualMistake(id){openModal('Add a mistake note',`<p class="small">Save something you noticed yourself or your teacher corrected.</p><textarea id="mistake-note" aria-label="Mistake note" placeholder="What should I pay attention to?"></textarea><button class="primary wide" id="save-mistake-note">Save note for ${esc(id)}</button>`);$('#save-mistake-note').onclick=()=>{const text=$('#mistake-note').value.trim();if(!text){toast('Add a short note first.');return;}addMistake(id,text.slice(0,1500));closeModal();toast('Added to your revision notebook.');render();};}
function hintHistory(){const entries=Object.entries(state.hints);openModal('Where I needed a hint',entries.length?entries.map(([id,n])=>{const a=id.split(':').map(Number);return `<div class="review-row"><div><strong>${esc(quran[a[0]-1]?.nameEn||'Qur’an')} · ${esc(id)}</strong><span class="small">${Number(n)||0} hints used</span></div><button class="secondary" data-review="${esc(id)}">Practise</button></div>`;}).join(''):'<p class="small">Hints you use during practice will appear here.</p>');}
function findVerse(){openModal('Find a verse by its words',`<p class="small">Enter at least four Arabic words. Shared phrases may have several matches; you choose the correct verse.</p><textarea id="find-words" lang="ar" dir="rtl" aria-label="Arabic words from a verse"></textarea><button class="primary wide" id="find-verse-go">Find matching verses</button><div id="found-verses"></div>`);$('#find-verse-go').onclick=()=>{const result=locatePassage(quran,$('#find-words').value);$('#found-verses').innerHTML=`<p class="small">${esc(result.reason)}</p>`+result.candidates.map(x=>`<button class="secondary wide" data-review="${x.surah}:${x.verse}">${esc(quran[x.surah-1].nameEn)} · ${x.surah}:${x.verse}</button>`).join('');};}
async function dispatch(action){switch(action){
 case 'mic-guide':microphoneGuide();break;case 'find-voice':findByVoice();break;case 'weak-practice':weakPractice();break;case 'hear-next':hearNextVerse();break;case 'play-chapter':closeModal();playChapter();break;case 'settings':settingsDialog();break;case 'speech-settings':settingsDialog('speech');break;case 'help':help();break;case 'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();setTheme();break;case 'focus':document.body.classList.toggle('focus');break;
 case 'reciter':reciterPicker();break;case 'playback-settings':playbackSettings();break;case 'play':if(state.mode==='read'&&reciters.find(r=>r.id===state.settings.reciter)?.kind==='surah')playChapter();else playQueue(selected(),{single:state.mode==='read'});break;case 'stop-audio':stopAudio();break;case 'listen':startListening();break;case 'retry':latestTranscript='';latestAlignment=null;render();startListening();break;case 'correct-audio':{const refs=expectedWords().refs,op=latestAlignment?.differences[0];if(op){const a=refs[op.index]?.split(':').map(Number);if(a)playQueue([verseRef(a[0],a[1])],{single:true});}else playQueue(selected(),{single:true});break;}
 case 'hide':state.hidden=!state.hidden;state.hintCount=0;$('#verses').innerHTML=versesHTML();updateRecitation();const b=$('[data-action="hide"]');if(b)b.textContent=state.hidden?'Reveal passage':'Hide passage';break;case 'hint':hint();break;case 'recite-now':state.mode='recite';state.hidden=true;render();break;
 case 'quiz':quiz();break;case 'quiz-options':quizOptions();break;case 'memorized':memorizedPicker();break;case 'prev-passage':nextPassage(-1);break;case 'next-passage':nextPassage(1);break;case 'jump':jumpDialog();break;
 case 'mark-practice':openModal('How did your passage feel?',`<p class="small">This schedules your next revision. Choose honestly; progress is not a score.</p><div class="confidence-row"><button data-mark-passage="strong">Strong</button><button data-mark-passage="practice">Needs practice</button><button data-mark-passage="forgotten">Forgotten</button></div>`);break;
 case 'due-review':{if($('#modal').open)closeModal();const due=dueEntries();if(due.length){const a=due[0][0].split(':').map(Number);state.view='practice';state.mode='recite';state.hidden=true;setSelection(a[0],a[1],a[1]);}else{state.view='revision';state.filter='all';render();}break;}
 case 'recent-review':{const x=state.sessions.at(-1);if(x){state.view='practice';state.mode='recite';setSelection(x.surah,x.from,x.to);}else toast('Practise a passage first, then return to it here.');break;}
 case 'new-lesson':if(state.settings.reviewFirst&&dueEntries().length){openModal('A little revision first?',`<p>You have ${dueEntries().length} passages due for review.</p><div class="button-row"><button class="primary" data-action="due-review">Review first</button><button class="secondary" id="continue-new">Start new lesson anyway</button></div>`);$('#continue-new').onclick=()=>{closeModal();state.mode='memorize';render();};}else{state.mode='memorize';render();}break;
 case 'goal':goalDialog();break;case 'export':exportProgress();break;case 'import':importProgress();break;case 'record':if($('#modal').open)closeModal();recording?stopRecording():startRecording();break;case 'recordings':recordingsDialog();break;case 'mic-check':microphoneCheck();break;case 'typed-check':typedCheck();break;case 'download-audio':downloadAudio();break;case 'audio-manager':audioManager();break;case 'hint-history':hintHistory();break;case 'bookmarks':openModal('Bookmarked verses',state.bookmarks.length?state.bookmarks.map(id=>{const a=id.split(':').map(Number);return `<div class="review-row"><strong>${esc(quran[a[0]-1].nameEn)} · ${esc(id)}</strong><button class="secondary" data-review="${esc(id)}">Open verse</button></div>`;}).join(''):'<p class="small">Use the bookmark button beside a verse to save it here.</p>');break;case 'find-verse':findVerse();break;
 case 'clear-progress':openModal('Clear your saved progress?',`<p>This deletes your practice history, confidence ratings, notes, hints and bookmarks. Recordings and downloaded audio are separate.</p><div class="button-row"><button class="secondary" data-action="export">Export first</button><button class="primary" id="confirm-clear-progress">Clear progress</button></div>`);$('#confirm-clear-progress').onclick=()=>{state.progress={};state.sessions=[];state.mistakes=[];state.hints={};state.bookmarks=[];save();closeModal();render();toast('Progress cleared.');};break;
 }}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-view]');if(!el)return;const d=el.dataset;if(d.view){if($('#modal').open)closeModal();navigate(d.view);}else if(d.mode){stopListening(false);speechStatus='Tap Start listening, allow the microphone, then recite.';speechProblem='';state.mode=d.mode;state.hidden=d.mode==='recite'||d.mode==='test';state.hintCount=0;latestAlignment=null;latestTranscript='';render();}else if(d.action)dispatch(d.action);else if(d.openSurah){state.view='practice';state.mode='read';state.hidden=false;setSelection(Number(d.openSurah),1,Math.min(5,quran[Number(d.openSurah)-1].verses.length));}else if(d.playVerse)playQueue([verseRef(state.selection.surah,Number(d.playVerse))],{single:true});else if(d.verseMenu)verseMenu(d.verseMenu);else if(d.favourite){const fav=state.settings.favouriteReciters;state.settings.favouriteReciters=fav.includes(d.favourite)?fav.filter(x=>x!==d.favourite):[...fav,d.favourite];save();el.textContent=state.settings.favouriteReciters.includes(d.favourite)?'★':'☆';el.setAttribute('aria-pressed',String(state.settings.favouriteReciters.includes(d.favourite)));filterReciters();}else if(d.reviewAudio){const [s,n]=d.reviewAudio.split(':').map(Number);if(verseRef(s,n))playQueue([verseRef(s,n)],{single:true});}else if(d.reciter){stopAudio();state.settings.reciter=d.reciter;save();closeModal();render();}else if(d.filter){state.filter=d.filter;render();}else if(d.review){const a=d.review.split(':').map(Number);closeModal();state.view='practice';state.mode='recite';state.hidden=true;setSelection(a[0],a[1],Math.min(a[1]+1,quran[a[0]-1].verses.length));}else if(d.resume){const a=d.resume.split(':').map(Number);state.view='practice';setSelection(...a);}else if(d.confidence){markConfidence(d.id,d.confidence);closeModal();render();toast('Confidence saved. Revision scheduled.');}else if(d.markPassage){for(const v of selected())markConfidence(ref(v),d.markPassage);addSession('Self-rated practice',0);closeModal();render();toast('Practice saved.');}else if(d.bookmark){if(state.bookmarks.includes(d.bookmark))state.bookmarks=state.bookmarks.filter(x=>x!==d.bookmark);else state.bookmarks.push(d.bookmark);save();closeModal();render();toast('Bookmark updated.');}else if(d.manualMistake)manualMistake(d.manualMistake);else if(d.similar)similarVerses(d.similar);else if(d.dismissMistake){state.mistakes=state.mistakes.filter(x=>x.id!==d.dismissMistake);save();render();toast('Possible mistake dismissed.');}else if(d.recordCompare){const a=d.recordCompare.split(':').map(Number);closeModal();state.view='practice';setSelection(...a);playQueue(selected(),{single:true});}else if(d.deleteRecord){const id=Number(d.deleteRecord);openModal('Delete this recording?',`<p>This deletes the local recording. Download it first if you want to keep it.</p><button class="primary wide" id="confirm-delete-record">Delete recording</button>`);$('#confirm-delete-record').onclick=async()=>{if(db)await dbRequest('recordings','readwrite',s=>s.delete(id));recordings=recordings.filter(r=>r.id!==id);recordingsDialog();};}});
$('#modal-close').onclick=closeModal;$('#modal').addEventListener('close',()=>{stopMicCheck();if(findingPassage){stopListening(false);findingPassage=false;}});$('#modal').addEventListener('cancel',stopMicCheck);
window.addEventListener('pagehide',()=>{stopListening(false);stopTracks();stopMicCheck();});
async function initialize(){try{let spelling;[quran,reciters,spelling]=await Promise.all([fetch('./quran.json').then(r=>{if(!r.ok)throw new Error();return r.json();}),fetch('./reciters.json').then(r=>{if(!r.ok)throw new Error();return r.json();}),fetch('./orthography.json').then(r=>{if(!r.ok)throw new Error();return r.json();})]);setOrthography(spelling);if(quran.length!==114)throw new Error();if(!Array.isArray(state.settings.favouriteReciters))state.settings.favouriteReciters=[];state.selection.surah=clamp(state.selection.surah,1,114);const count=current().verses.length;state.selection.from=clamp(state.selection.from,1,count);state.selection.to=clamp(state.selection.to,state.selection.from,count);state.view=['practice','library','revision','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'practice';db=await openDB();if(db)recordings=(await dbRequest('recordings','readonly',s=>s.getAll())).reverse();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});registerTools();}catch{$('#app-content').innerHTML='<div class="empty"><h1>Could not open the Qur’an.</h1><p>Connect to the internet for your first visit, then reload.</p><button class="primary" id="retry-load">Try again</button></div>';$('#retry-load').onclick=initialize;}}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'navigate_quran_passage',title:'Open Quran passage',description:'Navigate the visible reader to an explicit surah and verse range. Does not start audio or microphone.',inputSchema:{type:'object',properties:{surah:{type:'integer',minimum:1,maximum:114},from:{type:'integer',minimum:1},to:{type:'integer',minimum:1}},required:['surah','from','to'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Number.isInteger(input.surah)||!Number.isInteger(input.from)||!Number.isInteger(input.to)||!verseRef(input.surah,input.from)||!verseRef(input.surah,input.to)||input.to<input.from)throw new Error('Invalid Quran range');state.view='practice';setSelection(input.surah,input.from,input.to);return {selection:state.selection};}},{name:'read_quran_practice_state',title:'Read practice state',description:'Read the current passage, mode and counts of saved practice. Does not start audio or microphone.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {selection:state.selection,mode:state.mode,due:dueEntries().length,sessions:state.sessions.length,guest:state.guest};}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
hydrateIcons();initialize();
